diff --git a/src/ops/launcher/grouped_dynamic_conv.cu b/src/ops/launcher/grouped_dynamic_conv.cu
index d0987f7f..a8f31387 100644
--- a/src/ops/launcher/grouped_dynamic_conv.cu
+++ b/src/ops/launcher/grouped_dynamic_conv.cu
@@ -11,7 +11,7 @@
 namespace ginfer::ops::detail {
 namespace {

-#if GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120
+#if GINFER_COMPILED_CC == 86 || GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120
 constexpr int kMuseHidden      = 6656;
 constexpr int kMuseDynamicRows = 1664;
 constexpr int kMuseMaxColumns  = 128;
@@ -359,7 +359,7 @@ void grouped_dynamic_conv_prepare_launch(const Tensor& hidden, const Tensor& pro
     const int batch = hidden.ne[2];
     const int columns = width * batch;
     const int n = dynamic.ne[0];
-#if GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120
+#if GINFER_COMPILED_CC == 86 || GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120
     if (h == kMuseHidden && n == kMuseDynamicRows && columns <= kMuseMaxColumns &&
         is_aligned_16(hidden.data) && is_aligned_16(proj.data) && is_aligned_16(dynamic.data) &&
         is_aligned_16(out.data)) {

diff --git a/src/ops/linear/q4/q4_dispatch.cpp b/src/ops/linear/q4/q4_dispatch.cpp
index 9f2ee649..0b074c16 100644
--- a/src/ops/linear/q4/q4_dispatch.cpp
+++ b/src/ops/linear/q4/q4_dispatch.cpp
@@ -7,7 +7,8 @@ namespace {

 Q4Launch select_muse_q4_mma_launch(std::int32_t n, std::int32_t t) {
     if (t <= 32) { return launch_q4_mma_r64_c32; }
-#if defined(GINFER_COMPILED_CC) && GINFER_COMPILED_CC == 89
+#if defined(GINFER_COMPILED_CC) && \
+    (GINFER_COMPILED_CC == 86 || GINFER_COMPILED_CC == 89)
     if (t == 40 && n == 19968) { return launch_q4_mma_sm89_muse_n19968_t40_bk128; }
     if (t <= 48 && n != 19968) { return launch_q4_mma_sm89_muse_c48; }
 #endif
diff --git a/src/ops/linear/q4/q4_rowsplit_gemm_mma_sm89.cu b/src/ops/linear/q4/q4_rowsplit_gemm_mma_sm89.cu
index 69fa202a..ae480443 100644
--- a/src/ops/linear/q4/q4_rowsplit_gemm_mma_sm89.cu
+++ b/src/ops/linear/q4/q4_rowsplit_gemm_mma_sm89.cu
@@ -11,7 +11,8 @@
 namespace ginfer::ops::detail {
 namespace {

-#if defined(GINFER_COMPILED_CC) && GINFER_COMPILED_CC == 89
+#if defined(GINFER_COMPILED_CC) && \
+    (GINFER_COMPILED_CC == 86 || GINFER_COMPILED_CC == 89)
 using Q4MmaR32C40Schedule =
     Q4RowSplitMmaGemmSchedule<32, 40, 128, 16, 8, 2, 2, Q4FragmentPipeline::Serial, Cache::cg,
                               Cache::cg, Q4ScaleLoad::Pair32>;
@@ -62,7 +63,8 @@ void launch_route(const Tensor& x, const Weight& w, Tensor& out, cudaStream_t st

 void launch_q4_mma_sm89_muse_c48(const Tensor& x, const Weight& w, Tensor& out,
                                  cudaStream_t stream) {
-#if defined(GINFER_COMPILED_CC) && GINFER_COMPILED_CC == 89
+#if defined(GINFER_COMPILED_CC) && \
+    (GINFER_COMPILED_CC == 86 || GINFER_COMPILED_CC == 89)
     if (x.ne[1] <= 40) {
         launch_route<Q4MmaR32C40Schedule>(x, w, out, stream);
     } else {
@@ -73,20 +75,22 @@ void launch_q4_mma_sm89_muse_c48(const Tensor& x, const Weight& w, Tensor& out,
     (void)w;
     (void)out;
     (void)stream;
-    throw std::invalid_argument("Q4 Linear SM89 Muse C48 route requires sm_89");
+    throw std::invalid_argument("Q4 Linear SM8x Muse C48 route requires sm_86 or sm_89");
 #endif
 }

 void launch_q4_mma_sm89_muse_n19968_t40_bk128(const Tensor& x, const Weight& w, Tensor& out,
                                               cudaStream_t stream) {
-#if defined(GINFER_COMPILED_CC) && GINFER_COMPILED_CC == 89
+#if defined(GINFER_COMPILED_CC) && \
+    (GINFER_COMPILED_CC == 86 || GINFER_COMPILED_CC == 89)
     launch_route<Q4MmaR64C40K128Schedule>(x, w, out, stream);
 #else
     (void)x;
     (void)w;
     (void)out;
     (void)stream;
-    throw std::invalid_argument("Q4 Linear SM89 Muse N19968 T40 BK128 route requires sm_89");
+    throw std::invalid_argument(
+        "Q4 Linear SM8x Muse N19968 T40 BK128 route requires sm_86 or sm_89");
 #endif
 }
